'use strict';
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readIDs=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(id=>typeof id==='string'&&/^triunfobet:\d+$/.test(id)):[];}catch{return[];}};
const todayVenezuela=()=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Caracas',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(t=>parts.find(p=>p.type===t).value).join('-');};
const state={view:'explorar',provider:'triunfobet',sport:'basketball',league:'all',date:todayVenezuela(),search:'',favorites:readIDs('oddscope-favorites-v2'),compared:readIDs('oddscope-compared-v2').slice(0,3),drawer:null};
const feed={configured:false,loading:false,error:'',records:[],lastSync:null,sequence:0,loaded:false,leagues:[],sports:[],sportCounts:{}};
const recordKey=r=>r.provider+':'+r.eventId;
function availableSports(){return feed.sports.map(s=>({...s,emoji:SPORTS.find(x=>x.id===s.id)?.emoji||'◇'}));}
function visibleRecords(){const q=state.search.trim().toLocaleLowerCase('es');return feed.records.filter(r=>!q||[r.event.homeTeam.name,r.event.awayTeam.name,r.event.tournament.name].join(' ').toLocaleLowerCase('es').includes(q)).filter(r=>state.view!=='favoritos'||state.favorites.includes(recordKey(r))).filter(r=>state.view!=='comparar'||state.compared.includes(recordKey(r)));}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function setMenuOpen(open){$('#sidebar').classList.toggle('open',open);$('#nav-backdrop').hidden=!open;$('#menu-button').setAttribute('aria-expanded',String(open));}
function navigate(view){state.view=view;state.search='';setMenuOpen(false);location.hash=view==='explorar'?'partidos':view;render();}
function selectSport(id){setMenuOpen(false);state.sport=id;state.league='all';state.view='explorar';state.search='';feed.records=[];feed.lastSync=null;feed.error='';render();syncFeed();}
function render(){
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#fav-count').textContent=state.favorites.length;$('#compare-count').textContent=state.compared.length;
 $('#sport-total').textContent=availableSports().filter(s=>s.id!=='all').length;$('#sport-nav').className='sport-nav';$('#sport-nav').style.cssText='overflow-y:auto;min-height:100px;scrollbar-width:thin';$('#sport-nav').innerHTML=availableSports().map(s=>`<button class="nav-item ${state.sport===s.id?'active':''}" data-sport="${s.id}"><span class="sport-nav-icon">${s.emoji}</span>${escapeHTML(s.name)}<span class="nav-count">${s.id==='all'?Object.values(feed.sportCounts).reduce((a,b)=>a+b,0):feed.sportCounts[s.id]??''}</span></button>`).join('');
 $('#crumb').textContent={explorar:'Partidos',favoritos:'Mis favoritos',comparar:'Comparador',metodologia:'Metodología'}[state.view]||'Partidos';
 if(state.view==='metodologia'){renderSources();return;}
 renderFeedPage();
}
function renderFeedPage(){
 const sport=availableSports().find(s=>s.id===state.sport)||SPORTS.find(s=>s.id===state.sport)||{name:state.sport};const titles={explorar:'Partidos',favoritos:'Favoritos',comparar:'Comparador'};
 $('#main').innerHTML=`<div class="page-heading"><div><h1>${titles[state.view]||titles.explorar}</h1><p class="subheading">${escapeHTML(sport.name)} · Hora Venezuela</p></div><label class="date-control">${icon('calendar')}<input type="date" id="real-date" value="${state.date}" aria-label="Fecha de partidos"></label></div><div class="toolbar"><select id="real-league" aria-label="Competición"><option value="all">Todas las competiciones</option>${feed.leagues.filter(l=>state.sport==='all'||l.sport===state.sport).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(l=>`<option value="${escapeHTML(l.key)}">${escapeHTML(l.name)}</option>`).join('')||'<option value="">Sin competición integrada</option>'}</select><label class="search">${icon('search')}<input id="real-search" aria-label="Buscar partidos" placeholder="Buscar equipo o competición…"></label><button class="secondary-button" id="sync-button" ${feed.loading?'disabled':''}>${icon('clock')} ${feed.loading?'Consultando…':'Actualizar'}</button></div><div id="feed-feedback" role="status"></div><div id="real-match-list"></div>`;
 $('#real-league').value=state.league;$('#real-league').onchange=e=>{state.league=e.target.value;feed.sequence++;feed.loading=false;feed.records=[];feed.lastSync=null;render();syncFeed();};$('#real-search').value=state.search;$('#real-search').oninput=e=>{state.search=e.target.value;renderFeedList();};$('#real-date').onchange=e=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))return;state.date=e.target.value;feed.sequence++;feed.loading=false;feed.records=[];feed.lastSync=null;render();syncFeed();};$('#sync-button').onclick=()=>syncFeed();renderFeedList();
}
function renderFeedList(){
 if(!$('#real-match-list'))return;const allRecords=visibleRecords();const records=allRecords;
 $('#feed-feedback').innerHTML=feed.error?`<p class="data-error">No se pudieron actualizar los partidos.${feed.lastSync?' Mostrando datos anteriores.':''}</p>`:'';
 if(!records.length){$('#real-match-list').innerHTML=`<div class="empty">${icon(feed.loading?'clock':'search')}<h3>${feed.loading?'Cargando partidos…':feed.error?'No se pudieron cargar los partidos.':'Sin partidos'}</h3>${!feed.loading&&!feed.error?'<p>'+(state.view==='comparar'?'Añade partidos desde su ficha.':state.view==='favoritos'?'Guarda partidos con la estrella.':'Prueba otra fecha o filtro.')+'</p>':''}</div>`;return;}
 const groups=new Map();for(const r of records){const key=(availableSports().find(s=>s.id===r.sport)?.name||r.sport)+' · '+(r.event.tournament.name||'Sin competición');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}
 $('#real-match-list').innerHTML=`<p class="list-summary">${allRecords.length} partidos · ${new Set(records.map(r=>r.sport+':'+r.league)).size} competiciones</p>`+[...groups].map(([name,rs])=>`<section class="league-block"><div class="league-heading">${escapeHTML(name)}<span class="league-count">${rs.length} partidos</span></div>${rs.map(r=>{const e=r.event;const t=e.startTimestamp?new Date(e.startTimestamp*1000).toLocaleTimeString('es-ES',{timeZone:'America/Caracas',hour:'2-digit',minute:'2-digit'}):'—';return `<div class="real-fixture"><button class="star-button ${state.favorites.includes(recordKey(r))?'saved':''}" data-real-fav="${recordKey(r)}" aria-label="Guardar ${escapeHTML(e.homeTeam.name)}" aria-pressed="${state.favorites.includes(recordKey(r))}">${icon('star')}</button><span class="match-time">${t}</span><div><strong>${escapeHTML(e.homeTeam.name)}</strong><br><strong>${escapeHTML(e.awayTeam.name)}</strong></div><div class="real-scores">${escapeHTML(e.homeScore.current??'—')}<br>${escapeHTML(e.awayScore.current??'—')}</div><span class="drawer-meta">${escapeHTML(e.status.type==='finished'?'Finalizado':e.status.description||'Programado')}</span>${miniForecast(r)}</div>`;}).join('')}</section>`).join('');observeForecasts(records);
}
async function syncFeed(){
 if(feed.loading)return;feed.loading=true;const sequence=++feed.sequence;const date=state.date,sport=state.sport,league=state.league,provider=state.provider;if(['explorar','favoritos','comparar'].includes(state.view))render();
 try{const statusRes=await fetch(`/api/${provider}/status`,{cache:'no-store'});if(!statusRes.ok)throw new Error('El servidor local de datos no está disponible.');const status=await statusRes.json();if(sequence!==feed.sequence||provider!==state.provider)return;feed.configured=status.configured===true;feed.leagues=Array.isArray(status.leagues)?status.leagues:[];feed.sports=Array.isArray(status.sports)?status.sports:[];if(!feed.configured){feed.error=status.message||'La conexión de Triunfobet no está disponible.';return;}
  const res=await fetch(`/api/${provider}/matches?sport=${encodeURIComponent(sport)}&league=${encodeURIComponent(league)}&date=${encodeURIComponent(date)}`,{cache:'no-store'});const data=await res.json();if(!res.ok)throw new Error(data.message||'No se pudo consultar la fuente.');if(sequence!==feed.sequence||date!==state.date||sport!==state.sport||league!==state.league||provider!==state.provider)return;if(!Array.isArray(data.events))throw new Error('La fuente devolvió un formato de partidos no compatible.');const records=data.events.map(event=>({...MatchData.bundle({event}),provider,source:'Triunfobet',sport:event.sportKey||sport,league:event.leagueKey||league}));feed.leagues=data.leagues||feed.leagues;feed.sports=data.sports||feed.sports;feed.sportCounts=data.sportCounts||{[sport]:records.length};feed.records=records;feed.lastSync=data.fetchedAt;feed.error='';feed.loaded=true;
 }catch(err){if(sequence===feed.sequence)feed.error=err.message;}finally{if(sequence===feed.sequence){feed.loading=false;if(['explorar','favoritos','comparar','metodologia'].includes(state.view))render();}}
}
function renderSources(){
 $('#main').innerHTML=`<div class="page-heading"><h1>Metodología</h1></div><div class="method-copy"><details class="forecast-method"><summary>Cómo se calculan los porcentajes</summary><p>Los encuentros, mercados y cuotas proceden exclusivamente de Triunfobet. Se muestran solo sus mercados de Crear Apuesta. Cada porcentaje es implícito: 100 ÷ cuota decimal. Incluye el margen de la casa y no es una estimación estadística independiente. En líneas con devolución o liquidación parcial, no equivale a la probabilidad de acertar.</p><p>Los porcentajes corresponden a selecciones individuales; no se multiplican para calcular combinadas. Las cuotas suspendidas o ausentes no reciben porcentaje. El filtro muestra solo porcentajes estrictamente mayores al valor elegido.</p></details><details class="forecast-method"><summary>Cobertura y actualización</summary><p>Se consulta el catálogo de deportes de Triunfobet y los encuentros próximos y en directo que tenga disponibles. No se incluye un archivo de partidos terminados. El calendario y los horarios usan la zona de Venezuela.</p><p>La agenda se actualiza cada 60 segundos con la página visible. Las cuotas se consultan al acercarse el encuentro a la pantalla o abrir su ficha, con caché de 30 segundos. La ventana local de Chrome debe permanecer abierta para las consultas automáticas.</p><p>Última consulta: ${feed.lastSync?escapeHTML(new Date(feed.lastSync).toLocaleString('es-ES',{timeZone:'America/Caracas'})):'—'} (Venezuela).</p></details></div>`;
}

let drawerTrigger=null;
async function openRealEvent(id){
 const record=feed.records.find(r=>r.eventId===id);if(!record)return;state.drawer=id;drawerTrigger=document.activeElement;$('#overlay').hidden=false;$('#drawer').hidden=false;$('.app-shell').inert=true;$('#sidebar').inert=true;document.body.style.overflow='hidden';
 const e=record.event;$('#drawer').innerHTML=`<button id="close-real-drawer" class="drawer-close icon-button" aria-label="Cerrar detalle">${icon('close')}</button><h2 id="drawer-title">${escapeHTML(e.homeTeam.name)}<br>${escapeHTML(e.awayTeam.name)}</h2><p class="drawer-meta">${escapeHTML(e.tournament.name)}</p><button class="secondary-button" data-real-compare="${recordKey(record)}">${state.compared.includes(recordKey(record))?'Quitar del comparador':'Comparar partido'}</button><div id="real-forecast" role="status"></div>`;$('#close-real-drawer').onclick=closeDrawer;$('#close-real-drawer').focus();renderForecastPanel(id);ensureForecast(record).then(()=>{if(state.drawer===id)renderForecastPanel(id);});
}

function closeDrawer(){state.drawer=null;$('#overlay').hidden=true;$('#drawer').hidden=true;$('.app-shell').inert=false;$('#sidebar').inert=false;document.body.style.overflow='';if(drawerTrigger?.isConnected)drawerTrigger.focus();}
document.addEventListener('click',e=>{const sport=e.target.closest('[data-sport]'),view=e.target.closest('[data-view]'),event=e.target.closest('[data-real-event]'),fav=e.target.closest('[data-real-fav]'),comp=e.target.closest('[data-real-compare]');if(sport){if(feed.loading){feed.sequence++;feed.loading=false;}selectSport(sport.dataset.sport);}else if(view)navigate(view.dataset.view);else if(event)openRealEvent(Number(event.dataset.realEvent));else if(fav){const id=fav.dataset.realFav;state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];try{localStorage.setItem('oddscope-favorites-v2',JSON.stringify(state.favorites));}catch{}render();}else if(comp){const id=comp.dataset.realCompare;if(state.compared.includes(id))state.compared=state.compared.filter(v=>v!==id);else if(state.compared.length<3)state.compared.push(id);else return toast('Puedes comparar hasta tres encuentros.');try{localStorage.setItem('oddscope-compared-v2',JSON.stringify(state.compared));}catch{}closeDrawer();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.drawer)closeDrawer();setMenuOpen(false);}if(state.drawer&&e.key==='Tab'){const controls=[...$('#drawer').querySelectorAll('button,a,input,select,summary')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#real-search')?.focus();}});
$('#overlay').onclick=closeDrawer;$('#menu-button').onclick=()=>setMenuOpen(!$('#sidebar').classList.contains('open'));$('#nav-backdrop').onclick=()=>setMenuOpen(false);window.matchMedia('(max-width:900px)').addEventListener('change',()=>setMenuOpen(false));$('#help-button').onclick=()=>navigate('metodologia');$('#footer-info').onclick=()=>navigate('metodologia');$('.brand').onclick=e=>{e.preventDefault();navigate('explorar');};hydrateIcons();render();setTimeout(syncFeed,0);setInterval(()=>{if(!document.hidden&&!feed.loading)syncFeed();},60000);

try{localStorage.removeItem('oddscope-imports-v1');}catch{}
if(['#metodologia','#favoritos','#comparar'].includes(location.hash))navigate(location.hash.slice(1));else if(location.hash&&location.hash!=='#partidos')navigate('explorar');
